Given an array of integers, the task is to insert an element at a given position in the array.Examples:Input: arr[] = [10, 20, 30, 40], pos = 2, ele = 50Output: [10, 50, 20, 30, 40]Input: arr[] = [], pos = 1, ele = 20Output: [20]Input: arr[] = [10, 20, 30, 40], pos = 5, ele = 50Output: [10, 20, 30, 40, 50]Try It YourselfTable of Content[Approach 1] Using Built-In Methods[Approach 2] Using Custom Method[Approach 1] Using Built-In MethodsWe will use library methods like insert() in C++, Python and C#, add() in Java and splice() in JavaScript.
            C++

    // C++ program to insert given element at a given position
// in an array using in-built methods

#include <iostream>
#include <vector>
using namespace std;

int main() {  
    vector<int> arr = {10, 20, 30, 40};
  	int ele = 50;
    int pos = 2;
    cout << "Array before insertion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

  	// Insert element at the given position
    arr.insert(arr.begin() + pos - 1, ele);

    cout << "\nArray after insertion\n";
    for (int i = 0; i < arr.size(); i++)
        cout << arr[i] << " ";

    return 0;
}


