10 50 20 30 40 Time Complexity: O(n), where n is the size of the array.[Approach 2] Using Custom MethodTo add an element at a given position in an array, shift all the elements from that position one index to the right, and after shifting insert the new element at the required position. 
            C++

    // C++ program to insert given element at a given position
// in an array using custom method

#include <iostream>
#include <vector>
using namespace std;

int main() {  
    int n = 4;
    vector<int> arr = {10, 20, 30, 40, 0};
  	int ele = 50;
    int pos = 2;
    cout << "Array before insertion\n";
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";

  	// Shifting elements to the right
    for(int i = n; i >= pos; i--)
    	arr[i] = arr[i - 1];

    // Insert the new element at index pos - 1
    arr[pos - 1] = ele;

    cout << "\nArray after insertion\n";
    for (int i = 0; i <= n; i++)
        cout << arr[i] << " ";

    return 0;
}


